import { SegmentedGroup } from "@kitora/ui/button-group"

function SegmentedExample() {
  const [view, setView] = useState<"preview" | "code" | "split">("preview")
  const opts: { id: typeof view; label: string }[] = [
    { id: "preview", label: "Preview" },
    { id: "code", label: "Code" },
    { id: "split", label: "Split" },
  ]
  return (
    <SegmentedGroup>
      {opts.map((o) => (
        <button
          key={o.id}
          onClick={() => setView(o.id)}
          data-active={view === o.id || undefined}
          className="rounded px-2.5 py-1 text-[12px] font-medium text-muted-foreground transition-colors hover:text-foreground data-[active]:bg-card data-[active]:text-foreground data-[active]:shadow-sm"
        >
          {o.label}
        </button>
      ))}
    </SegmentedGroup>
  )
}

export function ButtonGroupSegmentedGroup() {
  return (
    <div className="flex flex-wrap items-center justify-center gap-3">
      <SegmentedExample />
    </div>
  )
}
